/** No employee query or amount preview. Native catalogue admin + actual Assistant/module/pause
 * gates run before any vocabulary projection in this same interval. Empty catalogue is valid. */
export async function readPayComponentModuleActionChoices(supplied:SessionContext){
 const ctx={...supplied,roles:supplied.roles?.slice(),grants:supplied.grants?.map(g=>({...g}))};
 try{return await withTenant(ctx,tx=>withReviewedPayComponentIntervalTx(tx,ctx,async fresh=>{
 const references=await reviewedPayComponentReferenceChoicesTx(tx,fresh),eaLines=countryPacks().flatMap(pack=>pack.eaReporting??[]).filter(line=>line.active).map(line=>({code:line.code,label:line.label}));
 const result=PayComponentActionChoices.parse({kind:'choices',references,roundingMethods:[...ROUNDING_METHODS],displayCategories:[...PAY_DISPLAY_CATEGORIES],eaLines:Array.from(new Map(eaLines.map(line=>[line.code,line])).values())});if(Buffer.byteLength(JSON.stringify(result))>49152)throw Error();return result;
 }));}catch{return PayComponentActionChoices.parse({kind:'unavailable'});}
}

/** Current assigned Payroll + company Rewards admin before unit labels/batch metadata. No pay rows. */
export async function readRewardsPostModuleActionChoices(supplied:SessionContext){
 const ctx={...supplied,roles:supplied.roles?.slice(),grants:supplied.grants?.map(g=>({...g}))};try{return await withTenant(ctx,async tx=>{
 const fresh=await assertReviewedRewardsPostActorTx(tx,ctx),metadata=await reviewedRewardPostChoiceMetadataTx(tx,fresh),result=RewardsPostActionChoices.parse({kind:'choices',...metadata});if(Buffer.byteLength(JSON.stringify(result))>49152)throw Error();return result;
 });}catch{return RewardsPostActionChoices.parse({kind:'unavailable'});}
}

/** Same actual Tx/current principal for label choices. No nested native read or employee data. */
export async function readPayrollCloseModuleActionChoices(supplied:SessionContext){
 const ctx={...supplied,roles:supplied.roles?.slice(),grants:supplied.grants?.map(g=>({...g}))};try{return await withTenant(ctx,async tx=>{
 const fresh=await assertReviewedPayrollCloseActorTx(tx,ctx),result=PayrollCloseActionChoices.parse({kind:'choices',...await reviewedPayrollCloseChoiceMetadataTx(tx,fresh)});if(Buffer.byteLength(JSON.stringify(result))>49152)throw Error();return result;
 });}catch{return PayrollCloseActionChoices.parse({kind:'unavailable'});}
}

/** Country-only fresh labels. No retired/login-only operation needs target disclosure. */
async function countryStatutoryBrowserResult(ctx:SessionContext,result:Awaited<ReturnType<typeof reopenCountryStatutoryReview>>){if(result.kind==='retired')return result;const employmentId=result.kind==='prepared'?result.review.review.employmentId:result.receipt.receipt.employmentId,personId=result.kind==='prepared'?result.review.review.personId:result.receipt.receipt.personId,labels=await withTenant(ctx,tx=>readReviewedCountryStatutoryLabelsTx(tx,ctx,employmentId,personId));return{...result,labels:CountryStatutoryLabels.parse(labels)};}
export async function readCountryStatutoryModuleActionChoices(supplied:SessionContext){const ctx={...supplied,roles:supplied.roles?.slice(),grants:supplied.grants?.map(g=>({...g}))};try{return await withTenant(ctx,async tx=>{const metadata=await reviewedCountryStatutoryChoiceMetadataTx(tx,ctx),result=CountryStatutoryActionChoices.parse({kind:'choices',...metadata});if(Buffer.byteLength(JSON.stringify(result))>COUNTRY_STATUTORY_ACTION_RESPONSE_BYTES)throw Error();return result;});}catch{return CountryStatutoryActionChoices.parse({kind:'unavailable'});}}
export async function readCountryStatutoryModuleActionEditable(supplied:SessionContext,employmentId:string){const ctx={...supplied,roles:supplied.roles?.slice(),grants:supplied.grants?.map(g=>({...g}))},id=z.guid().parse(employmentId);return withTenant(ctx,async tx=>CountryStatutoryEditable.parse(await readReviewedCountryStatutoryEditableTx(tx,ctx,id)));}
